50			t.Fatalf("买单应被 seq2 撤销且无剩余量: %+v", o)
51		}
52		// 撤销原因必须来自实际引发超限的 seq2@20，不能被后面的天价改写。
53		if !strings.Contains(o.Reason, "报价序号 2") || strings.Contains(o.Reason, "报价序号 3") {
54			t.Fatalf("撤单原因必须锚定 seq2，不得被 seq3 改写: %q", o.Reason)
55		}
56	
57		if e.ReservedCash() != 0 {
58			t.Fatalf("被撤订单的剩余现金占用必须释放: %d", e.ReservedCash())
59		}
60		if e.Cash() != 1_000_000 {
61			t.Fatalf("无成交时现金余额不得变化: %d", e.Cash())
62		}
63	
64		q, ok := e.CurrentQuote("A")
65		if !ok || q.Seq != 3 || q.Price != math.MaxInt64 {
66			t.Fatalf("最新报价应推进到链末 seq3@MaxInt64: %+v ok=%v", q, ok)
67		}
68		if e.HasGap("A") {
69			t.Fatal("补齐后缺口必须消失")
70		}
71	
72		// 链末天价下：持仓为 0、无有效买单，合计为 0——既未留下已撤单占用，
73		// 也没有为规避溢出而漏算（此处本就无持仓）。
74		st := e.PositionAmountStatus()
75		if !st.Enabled || st.Limit != 30 || st.Holding != 0 || st.BuyReserved != 0 || st.Total != 0 {
76			t.Fatalf("链末金额状态错误: %+v", st)
77		}
78	
79		// 只新增一条 seq2 引发的撤销记录，不得有任何拒绝记录。
80		recs := e.Records()
81		if len(recs) != recsBefore+1 {
82			t.Fatalf("应只新增一条撤单记录，实际新增 %d 条", len(recs)-recsBefore)
83		}
84		cr := recs[recsBefore]
85		if cr.Kind != RecordCanceled || cr.OrderID != bid {
86			t.Fatalf("新增记录必须是该买单的撤销记录: %+v", cr)
87		}
88		if cr.AmtEnabled != true || cr.AmtLimit != 30 || cr.AmtHolding != 0 ||
89			cr.AmtBuyReserved != 40 || cr.AmtTotal != 40 {
90			t.Fatalf("撤单记录应固化 seq2 判断时的金额: %+v", cr)
91		}
92		// 报价定位来自实际引发超限的 seq2@20，而非链末天价。
93		if cr.QuoteSeq != 2 || cr.QuotePrice != 20 || len(cr.AmtQuoteRefs) != 1 {
94			t.Fatalf("撤单记录的报价快照应锚定 seq2@20: quote=%d/%d refs=%+v",
95				cr.QuoteSeq, cr.QuotePrice, cr.AmtQuoteRefs)
96		}
97		if cr.AmtQuoteRefs[0] != (RiskQuoteRef{Symbol: "A", Seq: 2, Moment: 2, Price: 20}) {
98			t.Fatalf("撤单报价定位错误: %+v", cr.AmtQuoteRefs[0])
99		}
100	}
101	
102	// TestAmountGapFillPartialFillKeepsFilledHoldingExcludesCanceledRemaining 覆盖
103	// 部分成交买单：报价引发的撤销只取消未成交数量；已成交持仓在链末天价下继续
104	// 参与金额计算（且仍可表示），现金余额与已入账成交保持原值。
105	func TestAmountGapFillPartialFillKeepsFilledHoldingExcludesCanceledRemaining(t *testing.T) {
106		e, _ := NewEngine(1_000_000)
107		mustSetMax(t, e, "A", 20)
108		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
109		bid := mustBuy(t, e, "A", 10, 10)
110		// 部分成交 4 股 @8：现金按实际价扣 32；持仓 4、剩余买单 6。
111		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 8, Qty: 4}); err != nil {
112			t.Fatal(err)
113		}
114		// 持仓 4×10=40 + 剩余买单 6×10=60 = 100，上限恰为 100。
115		if _, err := e.SetPositionAmountLimit(100); err != nil {
116			t.Fatal(err)
117		}
118	
119		// P3 取 MaxInt64/5：4×P3 仍可表示（持仓要继续计入），6×P3 则溢出
120		// （若被撤的 6 股剩余量仍被计入，整批会误失败）。
121		p3 := int64(math.MaxInt64 / 5)
122		wantHolding := p3 * 4
123		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: p3}, 0)
124	
125		recsBefore := len(e.Records())
126		n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 2, Price: 12})
127		if err != nil {
128			t.Fatalf("部分成交场景下补齐必须成功: %v", err)
129		}
130		if n != 2 {
131			t.Fatalf("应生效 2 条报价，实际 %d", n)
132		}
133	
134		o, _ := e.Order(bid)
135		if o.Status != StatusCanceled || o.Filled != 4 || o.Remaining() != 0 {
136			t.Fatalf("只应撤销未成交的 6 股、保留已成交 4 股: %+v", o)
137		}
138		if !strings.Contains(o.Reason, "报价序号 2") {
139			t.Fatalf("撤销原因必须来自 seq2@12: %q", o.Reason)
140		}
141	
142		// 现金余额与已入账成交保持原值；剩余买单现金占用 6×10=60 必须释放。
143		if e.Cash() != 1_000_000-32 {
144			t.Fatalf("收敛撤单不得改动已成交现金结算: %d", e.Cash())
145		}
146		if e.ReservedCash() != 0 {
147			t.Fatalf("未成交部分的现金占用必须释放: %d", e.ReservedCash())
148		}
149		if e.Position("A") != 4 {
150			t.Fatalf("已成交持仓必须保留: %d", e.Position("A"))
151		}
152	
153		// 链末报价下：真实持仓 4×P3 继续计入（不为规避溢出而漏算），已撤剩余量不计入。
154		st := e.PositionAmountStatus()
155		if st.Holding != wantHolding || st.BuyReserved != 0 || st.Total != wantHolding {
156			t.Fatalf("链末应只剩可表示的真实持仓市值: %+v want=%d", st, wantHolding)
157		}
158	
159		q, _ := e.CurrentQuote("A")
160		if q.Seq != 3 || q.Price != p3 || e.HasGap("A") {
161			t.Fatalf("最新报价应推进到链末且缺口消失: %+v gap=%v", q, e.HasGap("A"))
162		}
163	
164		// 撤单记录固化 seq2 下撤销前金额与“被取消的剩余量 6”。
165		recs := e.Records()
166		cr := recs[recsBefore]
167		if cr.Kind != RecordCanceled || cr.Remaining != 6 || cr.Filled != 4 {
168			t.Fatalf("撤单记录应标明取消剩余 6 股、已成交 4 股: %+v", cr)
169		}
170		if cr.AmtHolding != 48 || cr.AmtBuyReserved != 72 || cr.AmtTotal != 120 || cr.AmtLimit != 100 {
171			t.Fatalf("撤单记录金额快照应为 seq2@12 下的值: %+v", cr)
172		}
173		if cr.QuoteSeq != 2 || cr.QuotePrice != 12 {
174			t.Fatalf("撤单报价定位必须来自 seq2: %+v", cr)
175		}
176		for _, r := range recs[recsBefore:] {
177			if r.Kind == RecordRejected {
178				t.Fatalf("成功补齐不得新增拒绝记录: %+v", r)
179			}
180		}
181	}
182	
183	// TestAmountGapFillLaterOverflowRollsBackEarlierAmountCancel 保留真正的溢出失败：
184	// seq2 本会撤掉编号最大的买单，但链末 seq3 使一条仍有效买单的金额占用溢出
185	// （2×(MaxInt64/2+1) 不可表示）。整批必须回滚——连 seq2 那次撤单、释放的
186	// 占用都不能留下，生效条数为零，只新增一条拒绝记录，等待中的 seq3 继续等待。
187	func TestAmountGapFillLaterOverflowRollsBackEarlierAmountCancel(t *testing.T) {
188		e, _ := NewEngine(1_000_000)
189		mustSetMax(t, e, "A", 20)
190		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
191		b1 := mustBuy(t, e, "A", 2, 10)                         // 占用 20，seq2 后保留
192		b2 := mustBuy(t, e, "A", 6, 10)                         // 占用 60，seq2@12 下本应先被撤销
193		if _, err := e.SetPositionAmountLimit(80); err != nil { // 20+60 恰满，设置时不撤单
194			t.Fatal(err)
195		}
196	
197		p3 := int64(math.MaxInt64/2 + 1) // 2×p3 溢出；6×p3 同样溢出
198		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: p3}, 0)
199	
200		recsBefore := len(e.Records())
201		n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 2, Price: 12})
202		if !errors.Is(err, ErrInt64Overflow) {
203			t.Fatalf("链末仍有效买单金额溢出必须返回包装 ErrInt64Overflow 的错误，实际 %v", err)
204		}
205		if n != 0 {
206			t.Fatalf("溢出时生效条数必须为零，实际 %d", n)
207		}
208	
209		// seq2 本会触发的撤单不得留下：两单都保持待成交，占用与资金回到提交前。
210		for _, id := range []int64{b1, b2} {
211			if o, _ := e.Order(id); o.Status != StatusPending {
212				t.Fatalf("回滚不得留下 seq2 的撤单，订单 %d 状态: %+v", id, o)
213			}
214		}
215		if o, _ := e.Order(b2); o.Remaining() != 6 {
216			t.Fatalf("b2 剩余量应保持 6: %+v", o)
217		}
218		if e.ReservedCash() != 80 || e.Cash() != 1_000_000 {
219			t.Fatalf("资金与占用必须保持提交前值: reserved=%d cash=%d", e.ReservedCash(), e.Cash())
220		}
221	
222		// 最新已生效报价停留在 seq1；原先等待的 seq3 继续等待。
223		q, _ := e.CurrentQuote("A")
224		if q.Seq != 1 || q.Price != 10 {
225			t.Fatalf("回滚后最新报价应停留在 seq1@10: %+v", q)
226		}
227		if !e.HasGap("A") {
228			t.Fatal("回滚后 seq3 必须仍在等待")
229		}
230		// 等待中的同内容报价重复提交仍是无操作（继续等待）。
231		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: p3}, 0)
232	
233		// 金额查询反映提交前的可表示状态（seq1 下合计 80）。
234		if st := e.PositionAmountStatus(); st.Holding != 0 || st.BuyReserved != 80 || st.Total != 80 {
235			t.Fatalf("回滚后金额状态应恢复提交前值: %+v", st)
236		}
237	
238		// 只新增一条说明原因的拒绝记录，且不得有任何撤单记录残留。
239		recs := e.Records()
240		if len(recs) != recsBefore+1 {
241			t.Fatalf("整批失败只能新增一条记录，实际 %d 条", len(recs)-recsBefore)
242		}
243		rj := recs[recsBefore]
244		if rj.Kind != RecordRejected || !rj.AmtEnabled || rj.AmtLimit != 80 {
245			t.Fatalf("应新增一条携带金额上限快照的拒绝记录: %+v", rj)
246		}
247		if !strings.Contains(rj.Reason, "序号 3") || !strings.Contains(rj.Reason, "int64") {
248			t.Fatalf("拒绝原因必须指明链中溢出的 seq3: %q", rj.Reason)
249		}
250	}
251	
252	// TestAmountGapFillLaterHoldingOverflowRollsBackEarlierCancel 覆盖溢出来自仍存在
253	// 的持仓市值：seq2 撤光买单剩余量后，链末 seq3 使已成交持仓 4×p3 溢出
254	// （p3=MaxInt64/4+1）。即使前面没有任何有效买单了，持仓本身不可表示仍要整批
255	// 回滚，seq2 的撤单同样不能留下。
256	func TestAmountGapFillLaterHoldingOverflowRollsBackEarlierCancel(t *testing.T) {
257		e, _ := NewEngine(1_000_000)
258		mustSetMax(t, e, "A", 20)
259		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
260		bid := mustBuy(t, e, "A", 4, 10)
261		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 10, Qty: 4}); err != nil {
262			t.Fatal(err)
263		}
264		b2 := mustBuy(t, e, "A", 2, 10) // 剩余买单占用 20
265		// 持仓 40 + 买单 20 = 60，上限恰为 60。
266		if _, err := e.SetPositionAmountLimit(60); err != nil {
267			t.Fatal(err)
268		}
269	
270		p3 := int64(math.MaxInt64/4 + 1) // 4×p3 溢出
271		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: p3}, 0)
272	
273		recsBefore := len(e.Records())
274		n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 2, Price: 12})
275		if !errors.Is(err, ErrInt64Overflow) || n != 0 {
276			t.Fatalf("链末持仓市值溢出必须整批失败且 0 条生效: n=%d err=%v", n, err)
277		}
278	
279		// seq2 本会撤销 b2（48+24=72>60），回滚后不得留下该撤销。
280		if o, _ := e.Order(b2); o.Status != StatusPending || o.Remaining() != 2 {
281			t.Fatalf("b2 必须保持待成交、剩余 2: %+v", o)
282		}
283		if e.Position("A") != 4 || e.Cash() != 1_000_000-40 || e.ReservedCash() != 20 {
284			t.Fatalf("持仓、现金与占用必须保持提交前值: pos=%d cash=%d reserved=%d",
285				e.Position("A"), e.Cash(), e.ReservedCash())
286		}
287		q, _ := e.CurrentQuote("A")
288		if q.Seq != 1 || !e.HasGap("A") {
289			t.Fatalf("最新报价停留 seq1 且 seq3 继续等待: q=%+v gap=%v", q, e.HasGap("A"))
290		}
291		if st := e.PositionAmountStatus(); st.Holding != 40 || st.BuyReserved != 20 || st.Total != 60 {
292			t.Fatalf("金额状态应恢复提交前值: %+v", st)
293		}
294		recs := e.Records()
295		if len(recs) != recsBefore+1 || recs[recsBefore].Kind != RecordRejected {
296			t.Fatalf("只能新增一条拒绝记录，实际 %d 条", len(recs)-recsBefore)
297		}
298	}
299	
300	// TestAmountGapFillRepresentableOverLimitStillCancelsQuoteByQuote 区分“超限”与
301	// “溢出”：链末高价使仍有效买单金额远超上限但仍可表示时，继续按已有规则撤单，
302	// 不得误当成整数溢出；且两条报价各自的撤单分别锚定各自的报价定位。
303	func TestAmountGapFillRepresentableOverLimitStillCancelsQuoteByQuote(t *testing.T) {
304		e, _ := NewEngine(1_000_000)
305		mustSetMax(t, e, "A", 20)
306		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
307		b1 := mustBuy(t, e, "A", 2, 10) // 20
308		b2 := mustBuy(t, e, "A", 6, 10) // 60，合计恰 80
309		if _, err := e.SetPositionAmountLimit(80); err != nil {
310			t.Fatal(err)
311		}
312	
313		// seq3 高价但仍可表示（2×1_000_000=2_000_000）；先等待。
314		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 1_000_000}, 0)
315	
316		// seq2@12：24+72=96 > 80，撤 b2 后 24 ≤ 80；
317		// seq3@1_000_000：b1 占用 2_000_000 仍超限但可表示，再撤 b1。
318		recsBefore := len(e.Records())
319		n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 2, Price: 12})
320		if err != nil {
321			t.Fatalf("可表示的超限必须按规则撤单而非报溢出: %v", err)
322		}
323		if n != 2 {
324			t.Fatalf("应生效 2 条，实际 %d", n)
325		}
326		if o, _ := e.Order(b2); o.Status != StatusCanceled || !strings.Contains(o.Reason, "报价序号 2") {
327			t.Fatalf("b2 应由 seq2 撤销: %+v", o)
328		}
329		if o, _ := e.Order(b1); o.Status != StatusCanceled || !strings.Contains(o.Reason, "报价序号 3") {
330			t.Fatalf("b1 应由链末 seq3 撤销: %+v", o)
331		}
332		if e.ReservedCash() != 0 {
333			t.Fatalf("两单剩余现金占用都应释放: %d", e.ReservedCash())
334		}
335		q, _ := e.CurrentQuote("A")
336		if q.Seq != 3 || e.HasGap("A") {
337			t.Fatalf("链末推进、缺口消失: q=%+v", q)
338		}
339		if st := e.PositionAmountStatus(); st.Holding != 0 || st.BuyReserved != 0 || st.Total != 0 {
340			t.Fatalf("撤光后合计应为零: %+v", st)
341		}
342	
343		// 两条撤单记录分别固化各自报价下的判断，不得互相改写。
344		var cancels []Record
345		for _, r := range e.Records()[recsBefore:] {
346			if r.Kind == RecordCanceled {
347				cancels = append(cancels, r)
348			}
349			if r.Kind == RecordRejected {
350				t.Fatalf("可表示的超限不得产生拒绝记录: %+v", r)
351			}
352		}
353		if len(cancels) != 2 {
354			t.Fatalf("应有两条撤单记录，实际 %d", len(cancels))
355		}
356		cB2, cB1 := cancels[0], cancels[1]
357		if cB2.OrderID != b2 || cB2.QuoteSeq != 2 || cB2.AmtBuyReserved != 96 || cB2.AmtTotal != 96 ||
358			len(cB2.AmtQuoteRefs) != 1 || cB2.AmtQuoteRefs[0] != (RiskQuoteRef{Symbol: "A", Seq: 2, Moment: 2, Price: 12}) {
359			t.Fatalf("b2 撤单快照必须锚定 seq2@12 与撤销前合计 96: %+v", cB2)
360		}
361		if cB1.OrderID != b1 || cB1.QuoteSeq != 3 || cB1.AmtBuyReserved != 2_000_000 || cB1.AmtTotal != 2_000_000 ||
362			len(cB1.AmtQuoteRefs) != 1 || cB1.AmtQuoteRefs[0] != (RiskQuoteRef{Symbol: "A", Seq: 3, Moment: 3, Price: 1_000_000}) {
363			t.Fatalf("b1 撤单快照必须锚定 seq3@1_000_000 与撤销前合计 2_000_000: %+v", cB1)
364		}
365	}
