1	package book
2	
3	import (
4		"errors"
5		"math"
6		"strings"
7		"testing"
8	)
9	
10	// setupAmt 准备：现金 1_000_000；A、B 已设置持仓限额并各有一条报价。
11	func setupAmt(t *testing.T) *Engine {
12		t.Helper()
13		e, _ := NewEngine(1_000_000)
14		mustSetMax(t, e, "A", 1_000)
15		mustSetMax(t, e, "B", 1_000)
16		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
17		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 1, Price: 20}, 1)
18		return e
19	}
20	
21	func TestAmountLimitDisabledByDefault(t *testing.T) {
22		e := setupAmt(t)
23		id := mustBuy(t, e, "A", 5, 10)
24	
25		st := e.PositionAmountStatus()
26		if st.Enabled || st.Limit != 0 || st.Holding != 0 || st.BuyReserved != 0 || st.Total != 0 {
27			t.Fatalf("未设置上限时查询除 Enabled 外必须为零: %+v", st)
28		}
29	
30		// 未设置时不改变基线行为：报价涨到天价也不撤单。
31		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 1_000_000}, 1)
32		if o, _ := e.Order(id); o.Status != StatusPending {
33			t.Fatalf("未设置金额上限时报价不得撤单: %+v", o)
34		}
35		for _, r := range e.Records() {
36			if r.AmtEnabled {
37				t.Fatalf("未设置时记录不得携带金额快照: %+v", r)
38			}
39		}
40	}
41	
42	func TestAmountLimitSetValidation(t *testing.T) {
43		e := setupAmt(t)
44	
45		if _, err := e.SetPositionAmountLimit(-1); err == nil {
46			t.Fatal("负上限必须报错")
47		}
48		if e.PositionAmountStatus().Enabled {
49			t.Fatal("负上限不得启用限额")
50		}
51	
52		// 首次设置为 0：允许且立即生效；同值重复设置无操作、无记录。
53		before := len(e.Records())
54		if _, err := e.SetPositionAmountLimit(0); err != nil {
55			t.Fatal(err)
56		}
57		if _, err := e.SetPositionAmountLimit(0); err != nil {
58			t.Fatal(err)
59		}
60		if len(e.Records()) != before {
61			t.Fatal("同值重复设置不得产生记录")
62		}
63		if st := e.PositionAmountStatus(); !st.Enabled || st.Limit != 0 {
64			t.Fatalf("零上限应已启用: %+v", st)
65		}
66	}
67	
68	func TestAmountZeroLimitRejectsAndCancelsAllBuys(t *testing.T) {
69		e := setupAmt(t)
70		b1 := mustBuy(t, e, "A", 2, 10) // 占用 20
71		b2 := mustBuy(t, e, "B", 1, 30) // 占用 30（限价高于报价）
72	
73		canceled, err := e.SetPositionAmountLimit(0)
74		if err != nil {
75			t.Fatal(err)
76		}
77		// 持仓为 0（0 不超限），合计 50 > 0：按编号降序撤 b2、b1。
78		if len(canceled) != 2 || canceled[0] != b2 || canceled[1] != b1 {
79			t.Fatalf("应按编号降序撤销 %d,%d，实际 %v", b2, b1, canceled)
80		}
81		if e.ReservedCash() != 0 {
82			t.Fatalf("撤单应释放全部现金占用: %d", e.ReservedCash())
83		}
84	
85		// 零上限禁止任何买单。
86		if _, err := e.Buy("A", 1, 1); err == nil {
87			t.Fatal("零上限必须禁止新买单")
88		}
89		st := e.PositionAmountStatus()
90		if !st.Enabled || st.Total != 0 || st.Holding != 0 || st.BuyReserved != 0 {
91			t.Fatalf("撤光后查询应全零: %+v", st)
92		}
93	
94		// 卖单与卖出成交不受影响（无持仓可卖时卖出会被基线拒绝，这里先建仓验证）。
95		if _, err := e.SetPositionAmountLimit(100); err != nil {
96			t.Fatal(err)
97		}
98		id := mustBuy(t, e, "A", 5, 10)
99		if _, err := e.Fill(Trade{TradeID: 1, OrderID: id, Symbol: "A", Side: Buy, Price: 10, Qty: 5}); err != nil {
100			t.Fatal(err)
101		}
102		if _, err := e.SetPositionAmountLimit(0); err != nil {
103			t.Fatal(err)
104		}
105		sid := mustSell(t, e, "A", 5, 1)
106		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 10, Qty: 5}); err != nil {
107			t.Fatal("持仓本身超限时卖出成交仍应允许")
108		}
109	}
