144	func TestAmountQuoteRiseCancelsDescendingAcrossSymbols(t *testing.T) {
145		e := setupAmt(t)
146		// A 持仓 4 股（@10 成交），现金扣 40。
147		id := mustBuy(t, e, "A", 4, 10)
148		if _, err := e.Fill(Trade{TradeID: 1, OrderID: id, Symbol: "A", Side: Buy, Price: 10, Qty: 4}); err != nil {
149			t.Fatal(err)
150		}
151		bA := mustBuy(t, e, "A", 2, 10) // 限价 10，报价 10 → 占用 20
152		bB := mustBuy(t, e, "B", 1, 20) // 限价 20，报价 20 → 占用 20
153		// 合计 = 持仓 40 + 买单 40 = 80。
154		if _, err := e.SetPositionAmountLimit(80); err != nil {
155			t.Fatal(err)
156		}
157	
158		// A 报价涨到 12：持仓 48、A 买单 24、B 买单 20，合计 92 > 80。
159		// 编号最大的 bB 先撤（释放 20）→ 72 ≤ 80；bA 保留。
160		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 12}, 1)
161		if o, _ := e.Order(bB); o.Status != StatusCanceled {
162			t.Fatalf("报价上涨应先撤销编号最大的 B 买单: %+v", o)
163		}
164		if o, _ := e.Order(bA); o.Status != StatusPending {
165			t.Fatalf("撤销一单后合计已不超限，A 买单应保留: %+v", o)
166		}
167		st := e.PositionAmountStatus()
168		if st.Holding != 48 || st.BuyReserved != 24 || st.Total != 72 {
169			t.Fatalf("撤单后金额错误: %+v", st)
170		}
171	
172		// 撤单记录携带判断时金额与各合约报价定位。
173		rec := lastAmountRecord(t, e, RecordCanceled)
174		if rec.AmtHolding != 48 || rec.AmtBuyReserved != 44 || rec.AmtTotal != 92 || rec.AmtLimit != 80 {
175			t.Fatalf("撤单记录应固化撤销前金额: %+v", rec)
176		}
177		if len(rec.AmtQuoteRefs) != 2 {
178			t.Fatalf("应保存 A(seq2@12)、B(seq1@20) 两个报价: %+v", rec.AmtQuoteRefs)
179		}
180		if rec.AmtQuoteRefs[0] != (RiskQuoteRef{Symbol: "A", Seq: 2, Moment: 2, Price: 12}) {
181			t.Fatalf("A 报价定位错误: %+v", rec.AmtQuoteRefs[0])
182		}
183		if rec.AmtQuoteRefs[1] != (RiskQuoteRef{Symbol: "B", Seq: 1, Moment: 1, Price: 20}) {
184			t.Fatalf("B 报价定位错误: %+v", rec.AmtQuoteRefs[1])
185		}
186	}
