226	func TestAmountSellOrderHoldingStillCountsUntilFill(t *testing.T) {
227		e := setupAmt(t)
228		if _, err := e.SetPositionAmountLimit(100); err != nil {
229			t.Fatal(err)
230		}
231		id := mustBuy(t, e, "A", 10, 10)
