233			t.Fatal(err)
234		}
235		// 持仓 100 已达上限：新买单被拒。
236		if _, err := e.Buy("A", 1, 1); err == nil {
237			t.Fatal("持仓已达上限必须拒绝新买单")
238		}
239	
240		// 挂卖单不提前抵减额度：卖单占用的 6 股仍计入持仓金额。
241		sid := mustSell(t, e, "A", 6, 10)
242		if st := e.PositionAmountStatus(); st.Holding != 100 || st.Total != 100 {
243			t.Fatalf("未成交卖单不得提前抵减额度: %+v", st)
244		}
245		if _, err := e.Buy("A", 1, 1); err == nil {
246			t.Fatal("卖单未成交前额度不得释放")
