248	
249		// 卖出成交后才减少持仓金额（10-6=4 股 × 10 = 40），释放 60 额度。
250		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 10, Qty: 6}); err != nil {
251			t.Fatal(err)
252		}
253		if st := e.PositionAmountStatus(); st.Holding != 40 || st.BuyReserved != 0 || st.Total != 40 {
254			t.Fatalf("卖出成交后应按实际持仓计金额: %+v", st)
255		}
256	}
