258	func TestAmountPartialBuyFillRecalculatesWithActualCash(t *testing.T) {
259		e := setupAmt(t)
260		if _, err := e.SetPositionAmountLimit(100); err != nil {
261			t.Fatal(err)
262		}
263		// 10 股限价 10：占用 100，恰满。
264		id := mustBuy(t, e, "A", 10, 10)
265		if st := e.PositionAmountStatus(); st.BuyReserved != 100 || st.Holding != 0 {
266			t.Fatalf("前置占用错误: %+v", st)
267		}
268	
269		// 部分成交 4 股 @8：现金按实际价 32 结算；持仓 4×10(报价)=40，
270		// 剩余买单 6×max(10,10)=60，合计仍 100；同一数量不计两处。
271		if _, err := e.Fill(Trade{TradeID: 1, OrderID: id, Symbol: "A", Side: Buy, Price: 8, Qty: 4}); err != nil {
272			t.Fatal(err)
273		}
274		if e.Cash() != 1_000_000-32 {
275			t.Fatalf("现金必须按实际成交价结算: %d", e.Cash())
276		}
277		if st := e.PositionAmountStatus(); st.Holding != 40 || st.BuyReserved != 60 || st.Total != 100 {
278			t.Fatalf("部分成交后应按实际持仓与剩余买单重算: %+v", st)
279		}
280	
281		// 报价涨到 12：持仓 48 + 剩余买单 72 = 120 > 100，撤销剩余买单。
282		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 12}, 1)
283		if o, _ := e.Order(id); o.Status != StatusCanceled || o.Filled != 4 {
284			t.Fatalf("应收敛撤销剩余 6 股且保留已成交 4 股: %+v", o)
