286		if st := e.PositionAmountStatus(); st.Holding != 48 || st.BuyReserved != 0 || st.Total != 48 {
287			t.Fatalf("撤单后只剩 4 股持仓市值: %+v", st)
288		}
289		if e.Cash() != 1_000_000-32 {
290			t.Fatal("收敛撤单不得重算已成交现金")
291		}
292	}
