				return 0, fmt.Errorf("报价序号 %d: %w", cur.Seq, ErrInt64Overflow)
			}
			riskTrigger = !simRestricted && val.Loss >= e.riskLossLimit
		}
		// 同条报价同时触发两项保护时，先按亏损规则模拟撤光全部有效买单。
		if riskTrigger {
