					Symbol:     symbol,
					AmtEnabled: true,
					AmtLimit:   e.amtLimit,
					Reason:     fmt.Sprintf("报价序号 %d 生效将使持仓金额或买单占用合计超出 int64 范围，整批拒绝", cur.Seq),
				}, st)
				return 0, fmt.Errorf("报价序号 %d: %w", cur.Seq, ErrInt64Overflow)
			}
